import {createHotelDirectoryUI} from './hotel-directory-ui.js';
import {createPreferencesUI} from './preferences-ui.js';
import {createJourneyUI} from './journey-ui.js';
const $=s=>document.querySelector(s);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',close:'m6 6 12 12M6 18 18 6',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',spark:'m12 2 2.6 7.4L22 12l-7.4 2.6L12 22l-2.6-7.4L2 12l7.4-2.6Z',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Zm6-2v16m6-14v16',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v5l3 2',calendar:'M5 5h14v16H5zM8 2v6m8-6v6M5 10h14',search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0m-2 5 6 6',leaf:'M20 3C10 1 3 7 5 14s13 9 15-11ZM5 21l10-12',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0m-9-1v6m0-10v1',check:'m4 12 5 5L20 6',up:'m6 15 6-6 6 6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',compass:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0m-6-3-2 6-6 2 2-6 6-2Z'};
Object.assign(paths,{
  pool:'M3 16q3-3 6 0t6 0 6 0M3 21q3-3 6 0t6 0 6 0M7 12V4a2 2 0 0 1 4 0M7 6h10M7 10h10M17 12V4a2 2 0 0 1 4 0',
  dining:'M5 3v6a3 3 0 0 0 6 0V3M8 3v18M18 3v18M18 3c-4 3-4 9 0 9',
  family:'M8 8a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM16 11a2 2 0 1 0 0-4 2 2 0 0 0 0 4ZM2 21v-6a6 6 0 0 1 12 0v6M14 14a4 4 0 0 1 8 0v7',
  gym:'M3 8v8M7 5v14M7 12h10M17 5v14M21 8v8',
  culture:'M3 5h18v7a9 9 0 0 1-18 0V5ZM7 9h2m6 0h2M8 15q4 4 8 0',
  architecture:'M3 21h18M5 21V8l7-5 7 5v13M9 21v-7h6v7M9 9h6'
});
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const state={view:'discover',category:'all',favorites:[],completed:[],location:'arrival',preferences:{minutes:120,style:'explore',party:'solo'},plan:null,answer:null,route:null,routeTo:'garden',modal:null,busy:false,progress:'',drawerError:null,connectionBusy:false,journey:{chapterId:'lines',seen:[],paused:false},confirmations:{}};
let boot,saveTimer,toastTimer,focusBeforeModal,journeyUI,preferencesUI,directoryUI,activeRequest;
const place=id=>boot.places.find(p=>p.id===id);
const photo=p=>p.image==='space'?'/assets/space.svg':`/assets/${esc(p.image)}.jpg`;
const entryParams=new URLSearchParams(location.search);
const choosingHotel=!entryParams.get('hotel');
const selectedHotel=entryParams.get('hotel')||'lohkah-xiamen';
const btn=(action,label,cls='primary',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
async function api(url,data,method='POST'){
  const r=await fetch(url,{method,headers:{'X-Stay-Hotel':selectedHotel,...(data?{'Content-Type':'application/json'}:{})},body:data?JSON.stringify(data):undefined});
  const result=await r.json();if(!r.ok)throw new Error(result.error||'请求未完成，请重试');return result;
}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600);}
function persist(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>api('/api/state',{favorites:state.favorites,completed:state.completed,location:state.location,journey:state.journey,preferences:state.preferences},'PUT').catch(()=>toast('暂未保存成功，请重试')),180);}
function go(view){state.view=view;closeModal(false);render();window.scrollTo({top:0,behavior:'instant'});}
function header(){
  if(choosingHotel){$('#header').innerHTML=`<a class="brand" href="/"><img src="/assets/mark.svg" alt=""><span class="brand-name">栖间<small>STAY WITHIN</small></span></a><span class="entry-header-note">从你的酒店开始</span>`;return;}
  const live=boot.connections.bailian.status==='connected';
  $('#header').innerHTML=`<button class="brand" data-action="view" data-view="discover" aria-label="栖间首页"><img src="/assets/mark.svg" alt=""><span class="brand-name">栖间<small>STAY WITHIN</small></span></button>
  <nav class="top-nav" aria-label="主导航">${(boot.hotel.tier==='basic'?[['discover','酒店资料']]:[['discover','发现酒店'],['experiences','自由探索'],['plan','我的安排'],...(boot.hotel.tier==='connected'?[]:[['map','酒店地图']])]).map(([v,n])=>`<button data-action="view" data-view="${v}" class="${state.view===v?'active':''}">${n}</button>`).join('')}</nav>
  <div class="head-right"><button class="connection-btn" data-action="connections"><i class="status-dot ${live?'live':''}"></i><span class="label">${live?'百炼已连接':'智能体连接'}</span></button><button class="icon-btn" data-action="hotels" aria-label="选择酒店">${icon('pin')}</button><button class="icon-btn" data-action="search-entry" aria-label="搜索与询问">${icon('search')}</button><button class="icon-btn" data-action="favorites" aria-label="查看收藏">${icon('heart')}${state.favorites.length?`<span class="count">${state.favorites.length}</span>`:''}</button></div>`;
}
function assistant(){
  if(choosingHotel){$('#assistant').innerHTML='';return;}
  if(boot.hotel.tier==='basic'){$('#assistant').innerHTML=`<nav class="mobile-nav" aria-label="移动导航"><button data-action="view" data-view="discover" class="active">${icon('spark')}酒店</button><button data-action="nearby">${icon('compass')}周边</button><button data-action="hotels">${icon('search')}换家酒店</button></nav>`;return;}
  $('#assistant').innerHTML=`<nav class="mobile-nav" aria-label="移动导航">${[['discover','发现','spark'],['experiences','探索','compass'],['plan','安排','calendar'],...(boot.hotel.tier==='connected'?[]:[['map','地图','map']])].map(([v,n,i])=>`<button data-action="view" data-view="${v}" class="${state.view===v?'active':''}">${icon(i)}${n}</button>`).join('')}</nav>`;
}
function footer(){return `<footer class="legal-note"><span>栖间 · 酒店体验智能体</span><a href="/tryout.html">体验反馈</a><button data-action="about">关于与来源 ↗</button></footer>`;}
function experienceMedia(p,compact=false){
  if(p.image&&p.image!=='space')return `<img src="${photo(p)}" alt="${esc(p.name)}相关图片" loading="lazy">`;
  const kind=({restaurant:'dining',lounge:'dining',pool:'pool',gym:'gym',spa:'leaf',family:'family',culture:'culture',sport:'compass',space:'architecture'})[p.kind]||({dining:'dining',wellness:'leaf',architecture:'architecture',activity:'compass'})[p.category]||'compass';
  return `<span class="experience-symbol symbol-${kind}${compact?' compact':''}" aria-hidden="true">${icon(kind)}</span>`;
}
function hotelImage(){return boot.hotel.image|| (boot.hotel.cover&&boot.hotel.cover!=='space'?`/assets/${esc(boot.hotel.cover)}.jpg`:null);}
function card(p){return `<article class="experience ${p.image==='space'?'without-photo':''}" data-action="detail" data-id="${p.id}" tabindex="0" role="button" aria-label="了解${esc(p.name)}"><div class="card-photo">${experienceMedia(p)}</div><div class="experience-copy"><span class="experience-kind">${esc(p.tag)}</span><div class="card-title"><h3>${esc(p.name)}</h3></div><p class="card-desc">${p.sourceKind==='platform-ai'?esc(p.scheduleRequired?'查看场次与参与方式':`建议预留 ${p.duration||30} 分钟 · 参与前确认费用与权益`):esc(p.intro)}</p>${p.image==='space'&&!p.imageUrl?'<span class="experience-image-note">暂无项目实景图</span>':''}</div><div class="experience-end"><button class="save-btn ${state.favorites.includes(p.id)?'saved':''}" data-action="save" data-id="${p.id}" aria-label="${state.favorites.includes(p.id)?'取消收藏':'收藏'}${esc(p.name)}" aria-pressed="${state.favorites.includes(p.id)}">${icon('heart')}</button>${icon('arrow')}</div></article>`;}
function categoryNav(){return `<div class="category-nav" role="group" aria-label="体验分类">${boot.categories.map(c=>`<button class="${state.category===c.id?'active':''}" data-action="category" data-category="${c.id}" aria-pressed="${state.category===c.id}">${esc(c.name)}</button>`).join('')}</div>`;}
function discover(){return boot.hotel.tier==='basic'?directoryUI.home():journeyUI.home();}
function experiences(){const all=boot.places.filter(p=>p.category!=='outside'&&!['paused','expired'].includes(p.contentState)),visible=all.filter(p=>state.category==='all'||p.category===state.category),image=hotelImage();return `<section class="explore-heading"><div><h1>探索酒店</h1><p>${esc(boot.hotel.name)}</p></div><button class="text-btn" data-action="search-experiences">查当前酒店体验 ${icon('search')}</button><button class="text-btn" data-action="nearby">探索周边 ${icon('arrow')}</button></section><div class="explore-layout"><aside class="explore-hotel">${image?`<div class="explore-hotel-photo"><img src="${esc(image)}" alt="${esc(boot.hotel.name)}酒店图片"><span>酒店图片</span></div>`:''}<h2>把喜欢的，<br>放进今天。</h2><p>浏览 ${all.length} 项体验，收藏喜欢的，<br>再按你的时间安排。</p>${btn('planner',`帮我安排 ${icon('arrow')}`)}<button class="text-btn" data-action="hotels">换一家酒店 ${icon('down')}</button></aside><section class="explore-index" aria-label="酒店体验列表">${categoryNav()}<div class="cards">${visible.length?visible.map(card).join(''):'<div class="experience-empty"><h2>这个分类还没有体验</h2><p>可以切换分类，或浏览酒店周边。</p></div>'}</div>${directoryUI.coverage()}</section></div>${footer()}`;}
function mapSvg(target=state.routeTo){
  const line=state.route?.to===target?state.route.points:null;
  return `<div class="map-frame"><div class="map-label"><span>${esc(boot.hotel.shortName||boot.hotel.name)} · 体验点位</span><span>空间示意</span></div><svg class="hotel-map" viewBox="0 0 960 680" role="img" aria-label="酒店体验点位示意图，非真实平面图">
  <defs><pattern id="water" width="40" height="24" patternUnits="userSpaceOnUse"><path d="M0 15q10-6 20 0t20 0" fill="none" stroke="#bccfc6" stroke-width="1"/></pattern><pattern id="garden-grid" width="24" height="24" patternUnits="userSpaceOnUse"><circle cx="12" cy="12" r="1" fill="#d1dcc1"/></pattern><filter id="shadow"><feDropShadow dx="0" dy="3" stdDeviation="5" flood-opacity=".06"/></filter></defs>
  <rect width="960" height="680" fill="#e9eddf"/><path d="M730-20C690 90 820 100 792 210S872 310 825 410s60 195 145 240V-20Z" fill="#d6e2da"/><path d="M730-20C690 90 820 100 792 210S872 310 825 410s60 195 145 240V-20Z" fill="url(#water)"/>
  <rect x="80" y="90" width="720" height="520" rx="150" fill="url(#garden-grid)"/><path d="M155 400H790M355 170V550M515 200V565M190 400V480" stroke="#d6dbc9" stroke-width="29" fill="none" stroke-linejoin="round"/><path d="M155 400H790M355 170V550M515 200V565M190 400V480" stroke="#f4f4e9" stroke-width="23" fill="none" stroke-linejoin="round"/>
  <g fill="#e3dece" stroke="#c8c6b5" stroke-width="1"><rect x="280" y="214" width="175" height="90" rx="4"/><rect x="465" y="250" width="160" height="84" rx="4"/><rect x="630" y="185" width="128" height="100" rx="4"/><rect x="265" y="480" width="130" height="85" rx="4"/><rect x="455" y="480" width="130" height="85" rx="4"/><rect x="135" y="355" width="110" height="90" rx="4"/></g>
  <g stroke="#c5cbb5" stroke-width="1" opacity=".7">${[0,1,2,3,4,5].map(i=>`<path d="M${295+i*25} 215v88"/>`).join('')}<path d="M470 272h150m-150 20h150m-150 20h150"/></g>
  <g fill="#cad8b9" stroke="#b5c7a0" stroke-width="1">${[[120,240,23],[190,190,33],[240,280,19],[650,510,25],[690,570,18],[200,540,26],[425,160,29],[600,100,18],[105,490,20],[435,445,16],[680,355,21],[80,360,16]].map(([x,y,r])=>`<circle cx="${x}" cy="${y}" r="${r}"/><circle cx="${x-5}" cy="${y-5}" r="${r*.7}" fill="#d5e0c7" stroke="none"/>`).join('')}</g>
  <rect x="675" y="430" width="130" height="42" rx="20" fill="#bfd5c9" stroke="#a7c3b4"/><text x="846" y="260" transform="rotate(76 846 260)" fill="#9fb8aa" font-size="17" letter-spacing="8" font-family="serif">水 畔</text>
  ${line?`<polyline class="map-route" points="${line.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#8d7950" stroke-width="3.5" stroke-linejoin="round"/>`:''}
  ${boot.places.filter(p=>p.id!=='activities'&&p.mapAvailable!==false&&p.category!=='outside'&&!['paused','expired'].includes(p.contentState)).map((p,i)=>`<g class="map-point ${p.id===target?'active':''}" data-action="map-point" data-id="${p.id}" role="button" tabindex="0" aria-label="选择${esc(p.name)}"><circle cx="${p.x}" cy="${p.y}" r="17" fill="#fafbf3" stroke="#a4b196" filter="url(#shadow)"/><text class="marker-number" x="${p.x}" y="${p.y+5}" text-anchor="middle">${String(i+1).padStart(2,'0')}</text><text class="name" x="${p.x}" y="${p.y+36}" text-anchor="middle">${esc(p.name.split(' · ')[0])}</text>${p.id===state.location?`<circle cx="${p.x+17}" cy="${p.y-16}" r="5" fill="#8eaa7b" stroke="#f9faf4" stroke-width="2"/>`:''}</g>`).join('')}
  <g transform="translate(860 560)" fill="none" stroke="#8c9f7e"><circle r="25"/><path d="m0-18 6 18-6 18-6-18Z"/><text x="0" y="-34" text-anchor="middle" font-size="10" fill="#839775" stroke="none">N · 示意</text></g></svg><div class="map-disclaimer">${icon('info')} 空间关系示意，非酒店实际平面图。路线未现场核验，不显示虚构距离或步行时间。</div></div>`;
}
function planView(){
  const p=state.plan;
  if(!p)return `<div class="section-title"><div><h1>我的安排</h1><p>把喜欢的体验，排进你的空闲时间。</p></div></div><div class="empty-state"><span class="empty-route" aria-hidden="true">${icon('calendar')}</span><h2>今天，想怎样度过？</h2><p>选好同行人、兴趣和空闲时间，生成一份可以随时调整的安排。</p>${btn('planner',`开始规划 ${icon('arrow')}`)}</div>${footer()}`;
  return `<div class="section-title"><div><h1>我的安排</h1><p>${esc(p.preferences.date)} · ${esc(p.preferences.start)} 开始 · ${p.preferences.minutes} 分钟 · ${p.engine==='bailian+rules'?'百炼＋规则检查':'规则安排，未使用AI'}</p></div>${btn('planner','调整安排','secondary small')}</div><div class="running-line">${icon('spark')}<span>${esc(p.explanation)}</span></div>${journeyUI.summary(p)}<div class="plan-layout"><section><div class="timeline">${p.items.length?p.items.map((item,i)=>{
    const pl=place(item.id);return `<div class="timeline-item"><div class="timeline-time"><span>${esc(item.start)}</span><small>${esc(item.end)}</small></div><div class="timeline-card"><div class="timeline-card-top">${experienceMedia(pl,true)}<div><h3>${esc(pl.name)}</h3><p>${esc(item.start)}—${esc(item.end)} · ${item.kind==='outside'?'外出预留':'建议停留'} ${item.minutes} 分钟</p><p>${['paused','expired'].includes(pl.contentState)?'资料已暂停或过期，请更换体验':item.kind==='outside'?'自行预留时间 · 未验证开放与实际交通':state.completed.includes(item.id)?'已自行标记体验完成':journeyUI.selfStatus(item.id)?'参与条件已由你自行确认':item.locked?'时段已保留 · 不代表已预约':'建议安排 · 尚未预约'}</p></div></div>${item.kind==='outside'?`<div class="outing-budget"><span>去程预留 ${item.outing.travelMinutes}′</span><span>停留 ${item.outing.visitMinutes}′</span><span>返程预留 ${item.outing.travelMinutes}′</span></div>`:''}${journeyUI.itemActions(item)}<div class="timeline-controls">${['paused','expired'].includes(pl.contentState)?`<button data-action="detail" data-id="${pl.id}">查看资料变更</button>`:item.kind==='outside'?`<button data-action="detail" data-id="outside">${icon('map')}地点与交通说明</button>`:`<button data-action="navigate" data-id="${pl.id}">${icon(boot.hotel.tier==='connected'||pl.mapAvailable===false?'info':'map')}${boot.hotel.tier==='connected'||pl.mapAvailable===false?'体验与参与':'查看位置'}</button>`}<div>${i?`<button data-action="move" data-index="${i}" aria-label="上移${esc(pl.name)}">${icon('up')}</button>`:''}<button data-action="remove" data-id="${pl.id}" aria-label="移除${esc(pl.name)}">${icon('trash')}</button><button data-action="complete" data-id="${pl.id}" aria-label="标记${esc(pl.name)}完成">${icon('check')}</button></div></div></div></div>`;
  }).join(''):'<p class="note">此时段暂无可安排体验，请调整条件。</p>'}</div>${p.skipped?.length?`<div class="warning">${p.skipped.map(x=>`${esc(place(x.id)?.name)}：${esc(x.reason)}`).join('<br>')}</div>`:''}<p class="note">停留时间是建议；项目间预留为规划缓冲，不是实测步行时间。所有体验均需确认现场开放及适用条件。</p><div class="two-actions" style="margin-top:22px"><a class="secondary small" href="/api/export?hotel=${encodeURIComponent(selectedHotel)}" download>${icon('download')}导出安排</a>${btn('planner','重新规划','secondary small')}</div></section><aside class="plan-map"><div class="stay-ticket"><div class="ticket-top">${icon('calendar')}<span>${esc(p.preferences.date)}</span></div><h2>${esc(boot.hotel.name)}</h2><div class="ticket-time"><strong>${esc(p.preferences.start)}</strong><span>开始</span></div><dl><div><dt>体验</dt><dd>${p.items.length} 项</dd></div><div><dt>可用时间</dt><dd>${p.preferences.minutes} 分钟</dd></div><div><dt>自由时间</dt><dd>${Math.max(0,p.unallocatedMinutes??p.freeMinutes??0)} 分钟</dd></div></dl><p>这是时间安排，不代表已预约。出发前请确认开放及参与条件。</p><a href="/api/export?hotel=${encodeURIComponent(selectedHotel)}" download>导出这份安排 ${icon('download')}</a></div>${boot.hotel.tier==='connected'?`<div class="plan-hotel-location">${icon('pin')}<p>${esc(boot.hotel.address)}</p>${boot.hotel.platformLink?`<a href="${esc(boot.hotel.platformLink)}" target="_blank" rel="noreferrer" aria-label="查看酒店详情">${icon('arrow')}</a>`:''}</div>`:mapSvg(p.items.find(x=>x.kind!=='outside')?.id||'garden')}</aside></div>${footer()}`;
}
function mapView(){
  const selected=place(state.routeTo);const p=selected&&!['paused','expired'].includes(selected.contentState)?selected:boot.places.find(x=>x.category!=='outside'&&!['paused','expired'].includes(x.contentState));const r=state.route;
  return `<div class="section-title"><div><div class="eyebrow">A LITTLE CLOSER TO YOUR NEXT MOMENT</div><h1>下一站，去哪儿？</h1><p>点选体验了解位置与服务，提前认识酒店空间。</p></div></div><div class="map-layout">${mapSvg(p.id)}<section class="route-panel"><div class="eyebrow">YOUR NEXT STOP</div><h2>${esc(p.name)}</h2><p>${esc(p.intro)}</p><label class="field"><span class="field-label">选择出发点</span><select id="route-from">${boot.places.filter(x=>x.id!=='activities'&&x.category!=='outside'&&!['paused','expired'].includes(x.contentState)).map(x=>`<option value="${x.id}" ${x.id===state.location?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><p class="note">目的地：${esc(p.location)}</p><div class="warning">未取得真实内部路网，当前仅演示点位联动。现场请使用酒店地图或向前台问路。</div>${(r?.to===p.id?r.steps:['选择出发点与目的地','查看点位之间的示意关系','实地路径与步行时间仍需核对']).map((s,i)=>`<div class="route-step"><span>${i+1}</span>${esc(s)}</div>`).join('')}${btn('route',`${icon('map')}查看示意路线`,'primary wide',`data-id="${p.id}"`)}<button class="text-btn" data-action="detail" data-id="${p.id}">看看这里有什么 ${icon('arrow')}</button>${btn('participate','参与前，确认一下','secondary wide',`data-id="${p.id}"`)}${btn('arrive','我已到达此处','secondary wide',`data-id="${p.id}"`)}<p class="note" style="margin-top:12px">由你主动更新位置；产品没有自动定位或追踪。</p></section></div>${footer()}`;
}
function render(){if(choosingHotel){document.body.classList.add('hotel-entry-page');header();assistant();$('#main').dataset.view='hotels';$('#main').innerHTML=directoryUI.landing()+footer();return;}document.body.classList.toggle('basic-page',boot.hotel.tier==='basic');document.body.classList.toggle('connected-page',boot.hotel.tier==='connected');if(boot.hotel.tier==='basic')state.view='discover';header();assistant();$('#main').dataset.view=state.view;$('#main').innerHTML=directoryUI.status()+({discover,experiences,plan:planView,map:mapView}[state.view]||discover)();}
function openModal(type,id){focusBeforeModal=document.activeElement;state.modal={type,id};state.drawerError=null;drawModal();document.body.style.overflow='hidden';for(const selector of ['#main','#header','#assistant'])$(selector).inert=true;setTimeout(()=>$('.drawer .icon-btn')?.focus(),0);}
function closeModal(restore=true){state.modal=null;$('#overlay').innerHTML='';document.body.style.overflow='';for(const selector of ['#main','#header','#assistant'])$(selector).inert=false;if(restore)focusBeforeModal?.focus?.();}
function drawerShell(label,content){return `<div class="backdrop" data-action="dismiss"><section class="drawer" role="dialog" aria-modal="true" aria-label="${esc(label)}"><div class="drawer-head"><span>${esc(label)}</span><button class="icon-btn" data-action="close" aria-label="关闭">${icon('close')}</button></div>${content}</section></div>`;}
function errorMarkup(){return state.drawerError?`<div class="error-box" role="alert">${esc(state.drawerError)}</div>`:'';}
function progressMarkup(){return state.busy?`<div class="progress"><span class="spinner"></span>${esc(state.progress||'正在整理…')}</div>`:'';}
function detailModal(id){const p=place(id);if(['paused','expired'].includes(p.contentState))return `<div class="drawer-content"><h2>${esc(p.name)}</h2><p>这项体验暂不展示。你保存的安排仍保留，可以选择其他体验。</p>${btn('view','浏览其他体验','primary','data-view="experiences"')}</div>`;if(p.category==='outside')return outingDetail(p);if(p.sourceKind==='platform-ai')return directoryUI.detail(p);return `${p.image!=='space'?`<img class="drawer-photo" src="${photo(p)}" alt="${esc(p.name)}相关图片">`:boot.hotel.image?`<figure class="hotel-overview-image"><img src="${esc(boot.hotel.image)}" alt="${esc(boot.hotel.name)}酒店整体图"><figcaption>酒店整体图片 · 非本项目实景</figcaption></figure>`:'<div class="missing-project-image">暂无该项目实景图</div>'}<div class="drawer-content"><div class="eyebrow">${esc(p.english)}</div><h2>${esc(p.name)}</h2><p>${esc(p.intro)}</p><div class="observation"><div class="eyebrow">LOOK A LITTLE CLOSER · 观察建议</div><p>${esc(p.prompt)}</p></div><p>${esc(p.story)}</p><dl class="fact-list"><div class="fact-row"><dt>位置</dt><dd>${esc(p.location)}</dd></div><div class="fact-row"><dt>开放时间</dt><dd>${esc(hours(p))} · 当日状态待酒店确认</dd></div><div class="fact-row"><dt>费用与权益</dt><dd>${esc(p.fee)}</dd></div><div class="fact-row"><dt>参与方式</dt><dd>${esc(p.booking)}</dd></div></dl><a class="source-link" href="${esc(p.source)}" target="_blank" rel="noreferrer">酒店官方资料 ↗ · 资料日期 ${esc(p.sourceCheckedAt||boot.hotel.checkedAt)}</a><div class="drawer-actions">${btn('save',`${icon('heart')}${state.favorites.includes(id)?'已收藏':'加入喜欢'}`,'secondary',`data-id="${id}"`)}${btn('navigate',`${p.mapAvailable===false?'参与方式':'查看位置'} ${icon('arrow')}`,'primary',`data-id="${id}"`)}</div><button class="text-btn" data-action="plan-with" data-id="${id}">${icon('calendar')}把这里放进我的安排</button><button class="primary wide" data-action="participate" data-id="${id}">${icon('info')}参与前，确认一下</button></div>`;}
function hours(p){const stamp=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;return p.windows==='seasonal-pool'?'5—10月 07:00—21:00；11—4月 09:00—18:00':Array.isArray(p.windows)?p.windows.map(x=>x.map(stamp).join('—')).join(' / '):'未取得明确时段';}
function partyField(){return preferencesUI.partyField();}
