function plannerModal(){const p=state.preferences;return `<div class="drawer-content"><div class="eyebrow">LET YOUR STAY UNFOLD</div><h2>这段时间，属于你。</h2><p>选一个节奏。随行智能体会查阅酒店资料，再与你的时间一起安排。</p><form id="plan-form">${partyField()}<div class="field"><span class="field-label">你有多少时间？</span><div class="chips">${[[30,'半小时'],[60,'1小时'],[120,'2小时'],[180,'3小时'],[240,'半天']].map(([m,n])=>btn('duration',n,`chip ${p.minutes===m?'active':''}`,`type="button" data-minutes="${m}" aria-pressed="${p.minutes===m}"`)).join('')}</div></div><div class="field"><span class="field-label">想怎么度过？</span><div class="chips">${[['explore','慢慢探索'],['relax','好好放松'],['food','一餐一茶'],['family','一起发现']].map(([s,n])=>btn('style',n,`chip ${p.style===s?'active':''}`,`type="button" data-style="${s}" aria-pressed="${p.style===s}"`)).join('')}</div></div><div class="form-row"><label class="field"><span class="field-label">体验日期</span><input name="date" type="date" required value="${esc(p.date||boot.clock.date)}"></label><label class="field"><span class="field-label">从几点开始</span><input name="start" type="time" required value="${esc(p.start||boot.clock.time)}"></label></div><label class="check"><input type="checkbox" name="noExtraSpend" ${p.noExtraSpend?'checked':''}><span>暂不安排额外消费<br><small>费用或包含情况不明的项目也会排除</small></span></label>${state.favorites.length?`<span class="field-label">优先考虑你喜欢的</span><div class="selected-pills">${state.favorites.map(id=>`<span>${esc(place(id).name)}</span>`).join('')}</div>`:''}${state.outing?`<label class="check"><input type="checkbox" name="includeOutside" ${p.includeOutside?'checked':''}><span>加入外出：${esc(state.outing.poi.name)}<br><small>往返交通与停留共预留 ${state.outing.totalMinutes} 分钟，按你的估算</small></span></label>`:''}${journeyUI.fixedNote()}<div id="plan-progress">${errorMarkup()}${progressMarkup()}</div><button type="submit" class="primary wide" ${state.busy&&!state.backgroundBusy?'disabled':''}>${icon('spark')}让随行智能体安排 ${icon('arrow')}</button><p class="note" style="margin-top:15px">通过百炼真实调用酒店查询工具，程序复核时间。未接入预约系统，不会自动预订或付款。</p></form></div>`;}
function connectionModal(){return `<div class="drawer-content"><div class="eyebrow">CONNECTED TO THE REAL WORLD</div><h2>智能体的服务连接</h2><p>接通与配置分开显示。只有实际调用成功，才会标记为已连接。</p>${[['bailian','阿里云百炼','理解当前场景、调用查询工具、组织建议与调整安排。'],['flyai','飞猪 FlyAI','查询酒店及周边旅行信息；不提供酒店内部路网或实时活动名额。']].map(([key,name,desc])=>{const s=boot.connections[key];return `<div class="connection-card"><div class="connection-title">${name}<small><i class="status-dot ${s.status==='connected'?'live':''}"></i>${s.status==='connected'?'实际调用成功':s.configured?'已配置，待验证':'尚未配置'}</small></div><p>${desc}</p>${s.ms?`<p class="note">最近一次 ${s.ms} ms · ${esc(s.checkedAt?.replace('T',' ').slice(0,19))} UTC</p>`:''}${s.error?`<p class="note">${esc(s.error)}</p>`:''}</div>`;}).join('')}<div id="connection-result">${errorMarkup()}</div>${btn('test-connections',state.connectionBusy?'正在验证真实连接…':'验证百炼与飞猪连接','primary wide',state.connectionBusy?'disabled':'')}<p class="note" style="margin-top:15px">密钥只在本机服务端读取，不会发送给网页。网页不提供密钥填写入口。</p>${state.lastTrace?`<div class="trace">最近一次智能体工具调用：<br>${state.lastTrace.map(t=>`${esc(t.tool)} · ${t.status==='success'?'成功':'未完成'} · ${t.ms}ms`).join('<br>')}</div>`:''}</div>`;}
function searchModal(){const ids=state.searchIds||[];return `<div class="drawer-content"><div class="eyebrow">YOUR STAY COMPANION</div><h2>查酒店体验，或换一家酒店</h2><p class="search-scope">当前酒店：${esc(boot.hotel.name)}</p><button class="secondary wide" data-action="search-hotels">搜索其他酒店 ${icon('arrow')}</button><form class="search-box" id="drawer-search"><input name="q" aria-label="搜索或提问" placeholder="搜索当前酒店的体验，或询问参与方式" value="${esc(state.searchText||'')}" maxlength="1500"><button aria-label="提交搜索">${icon('arrow')}</button></form>${errorMarkup()}${progressMarkup()}${state.searchAnswer?`<div class="observation"><div class="eyebrow">百炼随行建议</div><p>${esc(state.searchAnswer.intro)}</p></div>`:''}${ids.map(id=>{const p=place(id);return `<div class="result-row" role="button" tabindex="0" data-action="detail" data-id="${id}"><img src="${photo(p)}" alt=""><div><h3>${esc(p.name)}</h3><p>${esc(p.intro)}</p></div></div>`;}).join('')}${!state.searchText?`<div class="chips">${['有什么适合放松的体验？','今天不出酒店，帮我安排',`看看${boot.hotel.nearbyKeyword}附近`].map(q=>btn('suggest',q,'chip',`data-query="${q}"`)).join('')}</div>`:''}${!state.busy?btn('ask-agent',`${icon('spark')}让百炼结合资料回答`,'primary wide'):''}${state.searchAnswer?.followUps?.length?`<div class="trace">${state.searchAnswer.followUps.map(esc).join('<br>')}</div>`:''}</div>`;}
function liveModal(){const r=state.liveResult;return `<div class="drawer-content"><div class="eyebrow">STEP A LITTLE FURTHER</div><h2>酒店之外，也可以看看。</h2><p>探索${esc(state.nearbyKeyword||boot.hotel.nearbyKeyword||boot.hotel.city)}周边。</p>${state.outing?`<div class="outing-saved"><span>外出候选 · ${esc(state.outing.poi.name)}</span>${btn('planner','加入安排','text-btn')}${btn('clear-outing','移除','text-btn')}</div>`:''}${errorMarkup()}${progressMarkup()}${btn('fetch-nearby',`${icon('spark')}智能体查询周边`,'primary wide',state.busy&&!state.backgroundBusy?'disabled':'')}${r?`<p class="note" style="margin:15px 0">飞猪实际返回 ${r.items.length} 项 · ${esc(new Date(r.queriedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}))}</p>${r.items.length?r.items.map(x=>`<article class="live-item"><h3>${esc(x.name)}</h3><p>${esc(x.description.slice(0,180)||x.address||'暂无详细介绍')}</p><p class="note">${x.price?esc(x.price)+' · 详情确认价格':'费用未知'} · 开放时间与可用性未知</p>${x.link?`<a href="${esc(x.link)}" target="_blank" rel="noreferrer">查看飞猪详情 ↗</a>`:''}${x.id?btn('select-outing','留一段时间去这里','secondary small',`data-id="${esc(x.id)}"`):''}</article>`).join(''):'<p class="note">此次未返回地点，可以换个关键词查询。</p>'}`:''}</div>`;}
function favoritesModal(){return `<div class="drawer-content"><div class="eyebrow">A FEW LITTLE FAVOURITES</div><h2>把喜欢的留下。</h2><p>收藏的体验会优先进入规划，不代表已预订。</p>${state.favorites.length?state.favorites.map(id=>{const p=place(id);return `<div class="result-row"><img src="${photo(p)}" alt=""><div style="flex:1"><h3>${esc(p.name)}</h3><button class="text-btn" data-action="detail" data-id="${id}">查看体验</button></div><button data-action="save" data-id="${id}" aria-label="取消收藏${esc(p.name)}">${icon('close')}</button></div>`;}).join(''):'<div class="observation"><p>在体验卡上点一下爱心，把想去的地方留在这里。</p></div>'}${btn('planner',`按我的喜欢安排 ${icon('arrow')}`,'primary wide')}</div>`;}
function locationModal(){return `<div class="drawer-content"><div class="eyebrow">WHERE YOUR NEXT MOMENT BEGINS</div><h2>从哪里开始？</h2><p>选择你所在的地方，或想先认识的空间。这里由你选择，未启用自动定位。</p>${boot.places.filter(p=>p.id!=='activities'&&p.mapAvailable!==false&&p.category!=='outside'&&!['paused','expired'].includes(p.contentState)).map(p=>`<div class="result-row" data-action="scene" data-id="${p.id}" role="button" tabindex="0"><img src="${photo(p)}" alt=""><div><h3>${esc(p.name)}</h3><p>${esc(p.location)}</p></div></div>`).join('')}</div>`;}
function hotelsModal(){return directoryUI.selector();}
function aboutModal(){if(choosingHotel)return `<div class="drawer-content"><h2>栖间 · 酒店体验智能体</h2><p>先按城市和名称选择酒店，再浏览对应体验、查看来源并安排时间。</p><p>这是独立参赛产品，非酒店官方服务。安排不代表预约，项目开放、费用与权益需确认。</p></div>`;return `<div class="drawer-content"><div class="eyebrow">STAY WITHIN</div><h2>每一次入住，都有新发现。</h2><p>栖间将酒店空间、体验和你的时间连在一起：发现喜欢的，安排合适的，再了解如何参与。</p><div class="product-steps"><span>01 发现</span><span>02 规划</span><span>03 随行</span></div><h3>当前酒店 · ${esc(boot.hotel.name)}</h3><p>本产品为独立参赛样例，非酒店官方服务。</p><details class="guide-sources"><summary>酒店资料与使用说明</summary><p>酒店开放、消费和参与条件以现场为准。没有接入预约系统；用户确认仅为自行记录。地图为点位示意，非酒店实图。</p>${(boot.hotel.sources||[{name:'酒店资料',url:boot.hotel.source}]).map(x=>`<a class="source-link" href="${esc(x.url)}" target="_blank" rel="noreferrer">${esc(x.name)} ↗</a>`).join('')}<p class="note">资料日期 ${esc(boot.hotel.checkedAt)}。图片或产品空间视觉的使用方式以各页说明为准。公开使用图片前需核实使用范围。</p></details><button class="secondary wide" data-action="connections">服务连接 ${icon('arrow')}</button><a class="management-link" href="/manage" target="_blank" rel="noreferrer">本机资料管理 ↗</a></div>`;}

function drawModal(){if(!state.modal)return;const {type,id}=state.modal;const content=({detail:()=>detailModal(id),planner:plannerModal,connections:connectionModal,search:searchModal,nearby:liveModal,favorites:favoritesModal,location:locationModal,about:aboutModal,hotels:hotelsModal,profile:profileModal,outing:outingModal,guide:()=>journeyUI.guide(),participation:()=>journeyUI.participation(id),replacement:()=>journeyUI.replacement(id)}[type]||aboutModal)();$('#overlay').innerHTML=drawerShell({detail:'体验详情',planner:'规划你的入住时光',connections:'服务连接',search:'随行智能体',nearby:'酒店周边',favorites:'我的喜欢',location:'选择探索起点',about:'资料与说明',hotels:'我的入住',profile:'我的偏好',outing:'外出预留',guide:'探索酒店',participation:'参与前的确认',replacement:'只替换一项体验'}[type],content);}
async function agentCall(input){
  const background=input.action==='discover';
  if(activeRequest){if(activeRequest.background)activeRequest.controller.abort();else throw new Error('上一次整理还在进行，请稍候。');}
  const job={background,controller:new AbortController()};activeRequest=job;state.busy=true;state.backgroundBusy=background;state.progress='正在连接百炼…';state.drawerError=null;
  if(state.modal)drawModal();
  try{
    const response=await fetch('/api/agent',{method:'POST',headers:{'Content-Type':'application/json','X-Stay-Hotel':selectedHotel},body:JSON.stringify({...input,location:state.location}),signal:job.controller.signal});
    if(!response.ok){const e=await response.json();throw new Error(e.error||'智能体未完成请求');}
    const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',result;
    while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let split;
      while((split=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,split);buffer=buffer.slice(split+2);const type=block.match(/^event: (.+)$/m)?.[1];const raw=block.match(/^data: (.+)$/m)?.[1];if(!raw)continue;const data=JSON.parse(raw);
        if(type==='progress'&&activeRequest===job){state.progress=data.label;const target=$('.progress');if(target)target.innerHTML=`<span class="spinner"></span>${esc(data.label)}`;}
        if(type==='error')throw new Error(data.error);
        if(type==='result')result=data;
      }
    }
    if(!result)throw new Error('连接结束，但未收到完整结果。');state.lastTrace=result.traces;boot.connections=(await api('/api/health',undefined,'GET')).connections;return result;
  }finally{if(activeRequest===job){activeRequest=null;state.busy=false;state.backgroundBusy=false;state.progress='';}}
}
function saveForm(){const f=$('#plan-form')||$('#profile-form');if(f){state.preferences.date=f.elements.date?.value||state.preferences.date;state.preferences.start=f.elements.start?.value||state.preferences.start;state.preferences.noExtraSpend=f.elements.noExtraSpend?.checked===true;if(f.elements.includeOutside)state.preferences.includeOutside=f.elements.includeOutside.checked;}}
async function submitPlan(){
  saveForm();state.preferences.selected=[...state.favorites];persist();
  try{const answer=await agentCall({action:'plan',preferences:state.preferences});state.plan=answer.plan;state.answer=answer;go('plan');toast('安排已生成并保存到本机');}
  catch(e){state.drawerError=e.message;drawModal();}
}
async function search(q,ask=false){
  state.searchText=q.trim();const words=q.toLowerCase();state.searchIds=boot.places.filter(p=>(p.name+p.intro+p.story).toLowerCase().includes(words)||words.includes(p.name.split(' · ')[0])||((/茶|下午|小坐/.test(words))&&p.id==='tea')||(/水疗|护理|泡池|放松/.test(words)&&p.id==='spa')||(/建筑|设计|庭院/.test(words)&&p.id==='garden')).map(p=>p.id);
  state.searchAnswer=null;openModal('search');
  if(ask&&q){try{const result=await agentCall({action:'ask',text:q,preferences:state.preferences});state.searchAnswer=result;if(result.pointIds.length)state.searchIds=result.pointIds;drawModal();header();}catch(e){state.drawerError=e.message;drawModal();}}
}
async function navigate(id){if(place(id)?.mapAvailable===false){openModal('participate',id);return;}if(boot.hotel.tier==='connected'){openModal('detail',id);return;}state.routeTo=id;state.route=null;go('map');try{state.route=await api('/api/route',{from:state.location,to:id});render();}catch(e){toast(e.message);}}
async function editPlan(ids){try{state.plan=await api('/api/plan/edit',{ids});render();toast('安排已重新检查并保存');}catch(e){toast(e.message);}}
document.addEventListener('click',async e=>{
  const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;
  if(action==='enrich-hotel'){directoryUI.load();return;}
  if(action==='refresh-experiences'){if(state.busy&&!state.backgroundBusy){toast('请先完成当前安排');return;}directoryUI.load(true);return;}
  if(action==='related-nearby'){state.nearbyKeyword=el.dataset.keyword;state.liveResult=null;openModal('nearby');return;}
  if(preferencesUI&&await preferencesUI.handle(action,id))return;
  if(journeyUI&&await journeyUI.handle(action,el))return;
  if(action==='dismiss'){if(e.target===el)closeModal();return;}
  if(action==='close'){closeModal();return;}
  if(action==='view'){go(el.dataset.view);return;}
  if(action==='detail'){openModal('detail',id);return;}
  if(action==='category'){state.category=el.dataset.category;render();return;}
  if(action==='search-entry'){openModal('hotels');return;}
  if(action==='search-experiences'){openModal('search');return;}
  if(action==='search-hotels'){state.directoryQuery={city:'',keyword:state.searchText||''};openModal('hotels');return;}
  if(action==='switch-hotel'){if(state.busy&&!state.backgroundBusy){toast('请先完成当前安排，再切换酒店');return;}clearTimeout(saveTimer);try{if(!choosingHotel)await api('/api/state',{favorites:state.favorites,completed:state.completed,location:state.location,journey:state.journey,preferences:state.preferences},'PUT');activeRequest?.controller.abort();location.assign('/?hotel='+encodeURIComponent(id));}catch(e){toast('当前入住尚未保存，请稍后重试');}return;}
  if(['planner','connections','favorites','location','about','nearby','hotels','profile'].includes(action)){openModal(action);return;}
  if(action==='save'){e.stopPropagation();state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist();render();if(state.modal)drawModal();toast(state.favorites.includes(id)?'已加入喜欢':'已取消收藏');return;}
    if(action==='scene'){if(state.busy){toast('正在整理，请稍候');return;}state.location=id;state.answer=null;persist();go('discover');autoIntroduce();return;}
  if(action==='guide'){
    if(state.busy)return;const p=place(state.location);state.searchText=`请主动介绍我选择的${p.name}，给一个值得观察的细节和下一步选择，不编造设计背景。`;state.searchIds=[p.id];state.searchAnswer=null;openModal('search');
    try{const r=await agentCall({action:'guide',text:state.searchText});state.searchAnswer=r;state.answer={...r,context:state.location};state.searchIds=r.pointIds.length?r.pointIds:[p.id];drawModal();header();}catch(e){state.drawerError=e.message;drawModal();}return;
  }
  if(action==='plan-with'){if(!state.favorites.includes(id))state.favorites.push(id);persist();openModal('planner');return;}
  if(action==='duration'||action==='style'||action==='party'){saveForm();if(action==='duration')state.preferences.minutes=Number(el.dataset.minutes);else if(action==='party')state.preferences.party=el.dataset.party;else state.preferences.style=el.dataset.style;drawModal();return;}
  if(action==='navigate'){await navigate(id);return;}
  if(action==='map-point'){state.routeTo=id;state.route=null;render();return;}
  if(action==='route'){state.location=$('#route-from').value;persist();try{state.route=await api('/api/route',{from:state.location,to:id});render();}catch(e){toast(e.message);}return;}
  if(action==='arrive'){state.location=id;state.answer=null;persist();go('discover');toast('已按你的选择更新探索位置');return;}
  if(action==='complete'){state.completed=state.completed.includes(id)?state.completed.filter(x=>x!==id):[...state.completed,id];persist();render();toast('已保存你的体验记录');return;}
  if(action==='remove'){await editPlan(state.plan.items.map(x=>x.id).filter(x=>x!==id));return;}
  if(action==='move'){const ids=state.plan.items.map(x=>x.id),i=Number(el.dataset.index);[ids[i-1],ids[i]]=[ids[i],ids[i-1]];await editPlan(ids);return;}
  if(action==='test-connections'){
    if(state.connectionBusy)return;state.connectionBusy=true;drawModal();
    try{const r=await api('/api/connections/test',{});boot.connections=r.connections;state.drawerError=r.results.filter(x=>!x.ok).map(x=>x.error).join(' ')||null;toast(r.results.every(x=>x.ok)?'百炼与飞猪均实际调用成功':'已完成检查，请查看服务状态');}
    catch(e){state.drawerError=e.message;}finally{state.connectionBusy=false;if(state.modal?.type==='connections')drawModal();header();}return;
  }
  if(action==='suggest'){await search(el.dataset.query,true);return;}
  if(action==='ask-agent'){const q=$('#drawer-search input')?.value||state.searchText||'';if(!q.trim()){toast('先写一句你的需求');return;}await search(q,true);return;}
  if(action==='fetch-nearby'){
    try{const r=await agentCall({action:'nearby',text:`查询${state.nearbyKeyword||boot.hotel.nearbyKeyword||boot.hotel.city}周边适合了解的地点，保留缺失信息，不声称步行可达。`});state.liveResult=r.liveResult;if(!r.liveResult)state.drawerError='飞猪未返回有效查询结果，请重试。';drawModal();header();}catch(e){state.drawerError=e.message;drawModal();}return;
  }
});
document.addEventListener('submit',e=>{if(e.target.id==='hotel-search-form'){e.preventDefault();directoryUI.search(e.target);return;}if(e.target.id==='profile-form'){e.preventDefault();preferencesUI.applyProfile();return;}if(e.target.id==='outing-form'){e.preventDefault();preferencesUI.saveOuting(e.target);return;}if(e.target.id==='participation-form'){e.preventDefault();journeyUI.submitConfirmation(e.target);return;}if(e.target.id==='plan-form'){e.preventDefault();if(!state.busy||state.backgroundBusy)submitPlan();}if(['quick-search','drawer-search'].includes(e.target.id)){e.preventDefault();const q=new FormData(e.target).get('q')?.toString()||'';if(q.trim())search(q,false);}});
document.addEventListener('error',e=>{
  if(e.target.matches?.('.explore-hotel-photo img'))e.target.closest('.explore-hotel-photo').remove();
  if(e.target.matches?.('.stay-visual img')){const visual=e.target.closest('.stay-visual');e.target.outerHTML=`<div class="home-no-photo">${icon('architecture')}<span>酒店图片暂时无法加载</span></div>`;const note=visual.querySelector('.home-image-note');if(note)note.textContent='仍可浏览酒店体验';}
},true);
document.addEventListener('keydown',e=>{
  if(e.key==='Escape')closeModal();
  if(['Enter',' '].includes(e.key)&&e.target.matches('[role=button][data-action]')){e.preventDefault();e.target.click();}
  if(e.key==='Tab'&&state.modal){const nodes=[...$('.drawer').querySelectorAll('button:not([disabled]),a,input,select,textarea,summary,[tabindex="0"]')].filter(x=>x.getClientRects().length);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
});
async function init(){
  try{boot=choosingHotel?{hotel:{tier:'entry',city:'',name:''},hotels:[],state:{},clock:{date:'',time:''},connections:{}}:await api('/api/boot',undefined,'GET');Object.assign(state,{favorites:boot.state.favorites||[],completed:boot.state.completed||[],location:boot.state.location||'arrival',plan:boot.state.plan||null,outing:boot.state.outing||null,liveResult:boot.state.nearby||null,discovery:boot.discovery,journey:boot.state.journey||{chapterId:'lines',seen:[],paused:false},confirmations:boot.state.confirmations||{},preferences:{date:boot.clock.date,start:boot.clock.time,minutes:120,style:'explore',...boot.state.preferences}});if(state.preferences.date<boot.clock.date){state.preferences.date=boot.clock.date;state.preferences.start=boot.clock.time;}directoryUI=createHotelDirectoryUI({state,boot,esc,icon,btn,api,drawModal,footer,render,reload:init,choosingHotel});preferencesUI=createPreferencesUI({state,boot,esc,icon,btn,api,persist,render,openModal,closeModal,go,toast,saveForm,autoIntroduce});journeyUI=createJourneyUI({state,boot,esc,icon,btn,place,card,footer,categoryNav,api,persist,render,openModal,drawModal,closeModal,go,toast,photo,connectedDetail:p=>directoryUI.detail(p)});if(choosingHotel)state.directoryQuery={city:entryParams.get('city')||'',keyword:entryParams.get('findHotel')||''};render();if(!choosingHotel){if(boot.hotel.tier==='basic')directoryUI.load();else autoIntroduce();}}
  catch(e){$('#main').innerHTML=`<div class="initial"><p>${esc(e.message)}</p><button class="secondary" data-action="reload">重新加载</button></div>`;document.querySelector('[data-action=reload]')?.addEventListener('click',()=>location.reload());}
}
async function autoIntroduce(){
  if(boot.hotel.tier==='basic'||state.journey.paused)return;
  if(!boot.connections.bailian.configured||(state.busy&&!state.backgroundBusy)||state.journey.manual)return;
  const locationId=state.location,key=JSON.stringify(state.preferences);
  try{const answer=await agentCall({action:'discover',text:'根据同行人、兴趣、时段和可用时间，从候选中选一个最合适的体验。',preferences:state.preferences,completed:state.completed});if(state.location===locationId&&key===JSON.stringify(state.preferences)&&!state.journey.manual){state.answer={...answer,context:locationId};state.discovery=answer.discovery;if(state.view==='discover')render();}}
  catch{ /* Verified hotel facts remain usable; do not fabricate AI success. */ }
  finally{if(!state.busy){document.querySelectorAll('#plan-form button[type=submit], [data-action=fetch-nearby]').forEach(b=>b.disabled=false);document.querySelectorAll('.drawer .progress').forEach(p=>p.remove());}}
}
init();
